    if (expected.get().status() == GrantStatus.REVOKED) {
        return new SubjectDecision(expectedEpoch, CODE_CONSENT_REVOKED, null);
    }
    ConsentRepository.GrantRow latest = consentRepository
            .lockLatestGrant(subjectKey, purpose)
            .orElseThrow(() -> ApiException.notFound(CODE_GRANT_NOT_FOUND, "授权不存在"));
    if (latest.epoch() > expectedEpoch) {
        // 期望代次仍 ACTIVE 但已被新代替代（重新授权产生新当前代）
        return new SubjectDecision(expectedEpoch, CODE_EPOCH_SUPERSEDED, null);
    }
    return new SubjectDecision(expectedEpoch, null, purpose);
